#!/usr/bin/env python3
"""CLI to build the retrieval **vector index** as a single parquet artifact.

Runs the full ingestion pipeline off the serving path (intended for CI): parse
a local checkout of a Mintlify docs site -> chunk -> embed -> write the
embedded chunk rows to one self-contained parquet file and a sibling
``manifest.json``. ``--corpus`` selects the site: the Rasa docs repo
(``rasa-docs``) or the in-repo Mantle docs (``mantle-docs``).
The copilot then pulls this parquet and ingests the precomputed vectors
into its vector store during deployment.

The parquet is store-agnostic: columns are ``vector`` (fixed-size float32 list)
plus chunk metadata, and the build config (embed model/dim, corpus_version) is
embedded in the parquet schema metadata under the ``rasa_retrieval_meta`` key —
the deploy side asserts this matches its serving config before ingest.

Usage:
    python -m rasa.builder.document_retrieval.local.build_vector_index \
        --repo-path ~/workspace/codebase/documentation \
        --output .retrieval_index/docs_vectors.parquet

    python -m rasa.builder.document_retrieval.local.build_vector_index \
        --corpus mantle-docs \
        --repo-path mantle-docs \
        --output .retrieval_index/mantle_docs_vectors.parquet
"""

import argparse
import sys
from datetime import datetime, timezone
from pathlib import Path
from typing import List, Optional, Tuple

import pyarrow as pa
import pyarrow.parquet as pq
import structlog

from rasa.builder.document_retrieval.corpus import MintlifyCheckoutSource
from rasa.builder.document_retrieval.local.build_pipeline import build_chunk_rows
from rasa.builder.document_retrieval.local.config import EmbedConfig
from rasa.builder.document_retrieval.local.embedding import build_embedder
from rasa.builder.document_retrieval.local.parquet_artifact import (
    META_KEY,
    write_manifest,
    write_vectors_parquet,
)
from rasa.builder.document_retrieval.mintlify import MINTLIFY_SITES, RASA_DOCS_SITE
from rasa.builder.document_retrieval.source import SourceDocument

structlogger = structlog.get_logger()


def _load_corpus(
    corpus: str, repo_path: str, base_url: Optional[str]
) -> Tuple[List[SourceDocument], str]:
    """Parse a local checkout of the selected docs site into source documents.

    Args:
        corpus: Name of the docs site the checkout holds (a key of
            ``MINTLIFY_SITES``).
        repo_path: Root of the checkout, the directory holding ``docs.json``.
        base_url: Overrides the site's own base URL when set.

    Returns:
        A tuple ``(documents, corpus_version)``.

    Raises:
        SystemExit: If ``repo_path`` is not a Mintlify docs root.
    """
    site = MINTLIFY_SITES[corpus]
    if base_url:
        site = site.model_copy(update={"base_url": base_url})
    structlogger.info(
        "build_vector_index.load_corpus",
        corpus=corpus,
        repo_path=repo_path,
        base_url=site.base_url,
    )
    try:
        return MintlifyCheckoutSource(repo_path, site).load()
    except FileNotFoundError as e:
        raise SystemExit(str(e)) from e


def _validate(output_path: Path, expected_rows: int, expected_dim: int) -> None:
    """Re-read the artifact and assert shape + metadata, so CI fails on a bad build."""
    table = pq.read_table(str(output_path))
    if table.num_rows != expected_rows:
        raise SystemExit(
            f"Validation failed: wrote {expected_rows} rows but read "
            f"{table.num_rows} back from {output_path}."
        )
    vector_type = table.schema.field("vector").type
    if not pa.types.is_fixed_size_list(vector_type) or (
        vector_type.list_size != expected_dim
    ):
        raise SystemExit(
            f"Validation failed: vector column is {vector_type}, expected a "
            f"fixed_size_list<float32>[{expected_dim}]."
        )
    schema_meta = table.schema.metadata or {}
    if META_KEY.encode() not in schema_meta:
        raise SystemExit(
            f"Validation failed: missing '{META_KEY}' metadata in {output_path}."
        )


def _parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description=(
            "Build the retrieval vector index (embedded chunks) as a single "
            "parquet artifact, from a local checkout of a Mintlify docs site."
        )
    )
    parser.add_argument(
        "--output",
        required=True,
        help="Output path for the parquet artifact, e.g. "
        ".retrieval_index/docs_vectors.parquet.",
    )
    parser.add_argument(
        "--repo-path",
        required=True,
        help="Path to a local checkout of the docs site: the directory holding "
        "docs.json (the docs repo root, or mantle-docs/ in this repo).",
    )
    parser.add_argument(
        "--corpus",
        choices=sorted(MINTLIFY_SITES),
        default=RASA_DOCS_SITE.source,
        help="Docs site the checkout holds (default: %(default)s).",
    )
    parser.add_argument(
        "--base-url",
        default=None,
        help="Base URL the site's pages are served from. Defaults to the "
        "selected corpus's own site URL.",
    )
    parser.add_argument(
        "--embed-model",
        default=EmbedConfig.model_fields["embed_model"].default,
        help="Embedding model to build vectors with. Must match the model the "
        "copilot queries with at serving time.",
    )
    parser.add_argument(
        "--embed-cache-dir",
        default=None,
        help="Local embedding-model cache dir (else fastembed's default cache).",
    )
    parser.add_argument(
        "--manifest",
        default=None,
        help="Output path for manifest.json. Defaults to manifest.json beside "
        "--output.",
    )
    return parser.parse_args()


def main() -> int:
    args = _parse_args()

    output_path = Path(args.output).resolve()
    manifest_path = (
        Path(args.manifest).resolve()
        if args.manifest
        else output_path.with_name("manifest.json")
    )

    documents, corpus_version = _load_corpus(args.corpus, args.repo_path, args.base_url)
    if not documents:
        raise SystemExit(f"No documents parsed from {args.repo_path}.")

    embed_config = EmbedConfig(
        embed_model=args.embed_model, embed_cache_dir=args.embed_cache_dir
    )
    embedder = build_embedder(embed_config)

    rows = build_chunk_rows(documents, embedder)
    if not rows:
        raise SystemExit(f"No chunks produced from {len(documents)} source documents.")

    meta = {
        "embed_engine": embed_config.embed_engine,
        "embed_model": embed_config.embed_model,
        "embed_dim": embedder.dim,
        "corpus_version": corpus_version,
        "document_count": len(documents),
        "chunk_count": len(rows),
        "created_at": datetime.now(timezone.utc).isoformat(),
    }

    write_vectors_parquet(rows, meta, output_path)
    _validate(output_path, len(rows), embedder.dim)
    write_manifest(output_path, manifest_path)

    structlogger.info(
        "build_vector_index.done",
        corpus=args.corpus,
        output=str(output_path),
        manifest=str(manifest_path),
        document_count=len(documents),
        chunk_count=len(rows),
        embed_dim=embedder.dim,
        corpus_version=corpus_version,
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())
